create extension if not exists pgcrypto;
create table if not exists sellers(id text primary key,business_name text not null,owner_name text,phone text,whatsapp_number text,email text,address text,pincode text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),order_number bigint generated always as identity unique,customer_name text not null,customer_phone text not null,customer_address text not null,customer_pincode text not null,subtotal numeric(12,2) not null default 0,shipping_fee numeric(12,2) not null default 0,total numeric(12,2) not null default 0,status text not null default 'received' check(status in('received','confirmed','sent_to_sellers','completed','cancelled')),payment_status text not null default 'pending' check(payment_status in('pending','paid','failed','refunded')),payment_provider text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id bigint not null,seller_id text not null references sellers(id),seller_name_snapshot text,product_name_snapshot text not null,size_snapshot text,image_snapshot text,seller_price numeric(12,2) not null default 0,customer_price numeric(12,2) not null default 0,quantity integer not null check(quantity>0),line_total numeric(12,2) not null default 0,seller_commission numeric(12,2) not null default 0,seller_settlement numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table if not exists seller_orders(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,seller_id text not null references sellers(id),subtotal numeric(12,2) not null default 0,status text not null default 'pending' check(status in('pending','accepted','rejected','preparing','shipped','delivered')),created_at timestamptz not null default now(),unique(order_id,seller_id));
create index if not exists idx_order_items_order_id on order_items(order_id);create index if not exists idx_order_items_seller_id on order_items(seller_id);create index if not exists idx_seller_orders_seller_id on seller_orders(seller_id);create index if not exists idx_orders_status on orders(status);
alter table sellers enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table seller_orders enable row level security;
-- No public policies: FastAPI uses the Supabase service-role key.
